/**
 * The single business table of the app: one memo per customer name plus an
 * optional note and the moment it was recorded.
 *
 * Self-contained on purpose. The migration spells out every column, index and
 * nullability so an already-applied run keeps meaning the same thing after the
 * application evolves around it.
 */
export default defineMigration({
  name: '202609270001_create_customer_memos',
  async up({ builder }) {
    await builder.createCollection('customerMemos', (collection) => {
      collection.increments('id');
      collection.string('customerName', { length: 200, nullable: false });
      collection.text('note', { nullable: true });
      collection.datetime('createdAt', { nullable: false });
      collection.index('customerName');
      collection.index('createdAt');
    });
  },
  async down({ builder }) {
    await builder.dropCollection('customerMemos', { ifExists: true });
  },
});

import { defineSeed } from '@nocobase/db';

interface CustomerMemoSample {
  readonly customerName: string;
  readonly note: string | null;
  readonly createdAt: string;
}

/**
 * Fictional starting data. The seed is keyed by customer name and skips a name
 * that is already present, so re-running it neither duplicates the samples nor
 * overwrites a memo someone edited. Timestamps are fixed rather than generated
 * so the seed produces the same rows on every installation.
 */
const sampleMemos: readonly CustomerMemoSample[] = [
  {
    customerName: '星河智能科技有限公司',
    note: '年度软件授权已续约，关注第二季度上线的数据看板。',
    createdAt: '2026-08-12T02:30:00.000Z',
  },
  {
    customerName: '青禾食品有限公司',
    note: '对账周期从月结改为周结，财务联系人王敏。',
    createdAt: '2026-08-20T06:05:00.000Z',
  },
  {
    customerName: '远山物流股份有限公司',
    note: '计划新增两个仓库，需要重新评估接口对接排期。',
    createdAt: '2026-09-01T09:40:00.000Z',
  },
];

export default defineSeed({
  name: '202609270002_customer_memos_sample',
  async run(context) {
    const memos = context.repository<CustomerMemoSample>('customerMemos');
    for (const memo of sampleMemos) {
      const exists = await memos.exists({
        filter: { customerName: memo.customerName },
      });
      if (!exists) {
        await memos.createOne({ values: memo });
      }
    }
  },
});

/**
 * Closes the enclosing `RouteDialog` or `RouteDrawer`. Call it from a component rendered inside the overlay — its
 * body or its footer — never from the page that returns the overlay, which sits outside the provider.
 */
export function useRouteOverlay(): RouteOverlayContextValue {
  const value = useContext(RouteOverlayContext);
  if (!value) {
    throw new Error(
      'useRouteOverlay must be used inside RouteDialog or RouteDrawer',
    );
  }
  return value;
}

/** Route `/contacts/new`: create a contact in a dialog over the list. */
export default function ContactCreatePage(): ReactElement {
  const { t } = useTranslation();
  const { close } = useRouteOverlay();
  const { reload } = useOutletContext<SalesListOutletContext>();
  const [submitting, setSubmitting] = useState(false);

  return (
    <RouteDialog
      title={t('sales.contacts.form.createTitle')}
      description={t('sales.contacts.form.createDescription')}
      footer={
        <>
          <Button
            variant='outline'
            onClick={() => void close()}
            disabled={submitting}
          >
            {t('actions.cancel')}
          </Button>
          <Button type='submit' form={FORM_ID} disabled={submitting}>
            {submitting ? <Spinner data-icon='inline-start' /> : null}
            {submitting ? t('actions.saving') : t('actions.save')}
          </Button>
        </>
      }
    >
      <ContactForm
        formId={FORM_ID}
        onSubmittingChange={setSubmitting}
        onSubmitted={() => {
          reload();
          void close();
        }}
      />
    </RouteDialog>
  );

function Actions() {
  const { close, isClosing } = useRouteOverlay();
  return (
    <button disabled={isClosing} onClick={() => void close()}>
      Cancel
    </button>
  );
}

